#!/usr/bin/env python3

import narwhals as nw
import pandas as pd

def test_drop_issue():
    """Reproduce the pandas-like drop issue"""
    df_raw = pd.DataFrame({
        "a": [1, 3, 2],
        "b": [4, 4, 6],
        "z": [7.0, 8, 9]
    })

    df = nw.from_native(df_raw)

    print("Testing drop with list argument:")
    try:
        result1 = df.drop(["a", "b"])
        print("SUCCESS: df.drop(['a', 'b']) worked")
        print(result1.to_pandas())
    except Exception as e:
        print(f"ERROR: df.drop(['a', 'b']) failed: {e}")

    print("\nTesting drop with positional arguments:")
    try:
        result2 = df.drop("a", "b")
        print("SUCCESS: df.drop('a', 'b') worked")
        print(result2.to_pandas())
    except Exception as e:
        print(f"ERROR: df.drop('a', 'b') failed: {e}")

if __name__ == "__main__":
    test_drop_issue()
